//go:build integration

package tests

import (
	"context"
	"reflect"
	"strings"
	"testing"

	"github.com/bobmcallan/riskelle/internal/facts"
	"github.com/bobmcallan/riskelle/internal/score"
)

// toolHeader is the two-line header a tool writes on a file it owns.
const toolHeader = "// written by tool install\n// Do not edit: tool rewrites it\n"

// generatedHeaderFixture: on main, ext/tool.ts (header plus 300 lines),
// src/app.go and old/gen.go (marked); topic rewrites ext/tool.ts keeping the
// header, adds the marked api/client.go, edits src/app.go with a "do not edit"
// comment after its package clause, and deletes old/gen.go.
func generatedHeaderFixture(t *testing.T) string {
	t.Helper()
	dir := rulesFixture(t,
		map[string]string{
			"go.mod":      "module example.com/m\n",
			"ext/tool.ts": toolHeader + numbered("export const a", 300),
			"src/app.go":  "package app\n\nfunc A() {}\n",
			"old/gen.go":  "// Code generated by old. DO NOT EDIT.\npackage old\n\nvar X = 1\n",
		},
		map[string]string{
			"ext/tool.ts":   toolHeader + numbered("export const b", 100),
			"api/client.go": "// Code generated by gen. DO NOT EDIT.\n" + numbered("// line ", 79),
			"src/app.go":    "package app\n\n// do not edit lightly\nfunc A() {}\n",
		})
	fixtureGit(t, dir, "switch", "--quiet", "topic")
	fixtureGit(t, dir, "rm", "--quiet", "old/gen.go")
	fixtureGit(t, dir, "commit", "--quiet", "-m", "delete")
	fixtureGit(t, dir, "switch", "--quiet", "main")
	return dir
}

// TestGeneratedHeaderLeftOutOfScore: a changed file whose head blob carries a
// generated marker in its header is classed generated and left out of size,
// degree and untested; a marker after code, or in a deleted file, is not read.
func TestGeneratedHeaderLeftOutOfScore(t *testing.T) {
	f, res, err := collectAndScore(t, generatedHeaderFixture(t))
	if err != nil {
		t.Fatalf("rules.Score: %v", err)
	}
	want := map[string][]facts.Class{
		"api/client.go": {facts.ClassGenerated},
		"ext/tool.ts":   {facts.ClassGenerated},
		"old/gen.go":    nil,
		"src/app.go":    nil,
	}
	if len(f.Files) != len(want) {
		t.Fatalf("files %+v, want %v", f.Files, want)
	}
	for _, file := range f.Files {
		if w, ok := want[file.Path]; !ok || !reflect.DeepEqual(file.Classes, w) {
			t.Errorf("%s classes %v, want %v", file.Path, file.Classes, w)
		}
	}
	point := func(measure string) score.Point {
		t.Helper()
		for _, p := range res.Breakdown {
			if p.Measure == measure {
				return p
			}
		}
		t.Fatalf("no %s in %+v", measure, res.Breakdown)
		return score.Point{}
	}
	kept := []string{"old/gen.go", "src/app.go"}
	if p := point(score.MeasureSize); !reflect.DeepEqual(p.Excluded, []string{"api/client.go", "ext/tool.ts"}) || !reflect.DeepEqual(p.From, kept) {
		t.Errorf("size from %v excluded %v, want from %v excluded [api/client.go ext/tool.ts]", p.From, p.Excluded, kept)
	}
	if p := point(score.MeasureDegree); !reflect.DeepEqual(p.From, kept) {
		t.Errorf("degree from %v, want %v", p.From, kept)
	}
	if p := point(score.MeasureTests); !reflect.DeepEqual(p.From, kept) {
		t.Errorf("untested from %v, want %v", p.From, kept)
	}
}

// TestGeneratedHeaderInEstimate: a planned path is read at the target, so an
// existing marked file is classed generated as the score will find it; a
// planned new file is classed by path only.
func TestGeneratedHeaderInEstimate(t *testing.T) {
	dir := generatedHeaderFixture(t)
	p, err := facts.ReadPlan(strings.NewReader(`{"target": "main", "files": [
		{"path": "ext/tool.ts", "added": 100, "removed": 300},
		{"path": "api/new.go", "added": 50}]}`))
	if err != nil {
		t.Fatalf("ReadPlan: %v", err)
	}
	f, err := facts.Predict(context.Background(), dir, p)
	if err != nil {
		t.Fatalf("Predict: %v", err)
	}
	want := map[string][]facts.Class{"api/new.go": nil, "ext/tool.ts": {facts.ClassGenerated}}
	if len(f.Files) != len(want) {
		t.Fatalf("files %+v, want %v", f.Files, want)
	}
	for _, file := range f.Files {
		if w, ok := want[file.Path]; !ok || !reflect.DeepEqual(file.Classes, w) {
			t.Errorf("%s classes %v, want %v", file.Path, file.Classes, w)
		}
	}
}
